// Some portions generated by Co-Pilot
import { render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import BannerMiddle from "../index";

vi.mock("../announcements", () => ({
  currentAnnouncements: [
    {
      title: "Support Eclipse Temurin",
      description: "Community support keeps Eclipse Temurin available.",
      cta: "Learn more",
      ctaLink: "/sustainers/",
      startDate: "2026-10-01T00:00:00Z",
      endDate: "2026-10-31T23:59:59Z",
    },
    {
      title: "Expired announcement",
      description: "This announcement is no longer active.",
      cta: "Read more",
      ctaLink: "/members/",
      endDate: "2025-12-31T23:59:59Z",
    },
  ],
}));

describe("Supporting homepage announcement", () => {
  beforeEach(() => {
    vi.useFakeTimers({
      now: new Date("2026-10-27T12:00:00Z"),
      shouldAdvanceTime: true,
    });
  });

  afterEach(() => vi.useRealTimers());

  it("renders a supporting aside with the active announcement and existing link behaviour", () => {
    render(<BannerMiddle />);
    expect(screen.getByRole("complementary")).toBeInTheDocument();
    expect(
      screen.getByRole("heading", { name: "Support Eclipse Temurin" }),
    ).toBeVisible();
    const link = screen.getByRole("link", { name: "Learn more" });
    expect(link).toHaveAttribute("href", "/sustainers/");
    expect(link).toHaveAttribute("target", "_blank");
    expect(link).toHaveAttribute("rel", "noopener noreferrer");
    expect(screen.queryByText("Expired announcement")).not.toBeInTheDocument();
  });

  it("does not render when every announcement is expired", () => {
    vi.setSystemTime(new Date("2027-01-01T12:00:00Z"));
    const { container } = render(<BannerMiddle />);
    expect(container).toBeEmptyDOMElement();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<BannerMiddle />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
